for old, new in (("Labels are law: **demonstrated** (executed against the released, unedited chain at the stated convention, on this platform)",
                  "Labels are law: **demonstrated** (executed against the released, unedited chain at the stated convention, on this platform — for two-cell rows, under §2's in-model coupling)"),):
    assert old in T, old[:60]; T = T.replace(old, new)
